const (
	// MCP hosts can fan out tool calls faster than a human CLI session.
	// Keep them on the same polite-client limiter path instead of disabling
	// pacing with rate=0; users can still tune human CLI calls with --rate-limit.
	defaultMCPRateLimit = 2
)

// RegisterTools registers all API operations as MCP tools.
func RegisterTools(s *server.MCPServer) {
	installFreshTenantGate(s)
	s.AddTool(
		mcplib.NewTool("graphql_query",
			mcplib.WithDescription("Execute a raw GraphQL query or mutation against the Best Food Trucks API. Required: query. Optional: operationName, variables (default: map[]). Returns the new graphql_response."),
			mcplib.WithString("operationName", mcplib.Description("GraphQL operation name (optional; informational for multi-operation documents)")),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Full GraphQL query or mutation document text")),
			mcplib.WithObject("variables", mcplib.Description("GraphQL variables as a JSON object")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(true),
		),
		makeAPIHandler("POST", "/graphql", true, false, nil, mcpPageConfig{}, []mcpParamBinding{{PublicName: "operationName", WireName: "operationName", Location: "body"}, {PublicName: "query", WireName: "query", Location: "body"}, {PublicName: "variables", WireName: "variables", Location: "body"}}, []string{}),
	)
	// Intent tools — higher-level compositions declared in the spec or lifted from recipes.
	RegisterIntents(s)

	// Context tool — front-loaded domain knowledge for agents.
	// Call this first to understand the API taxonomy, query patterns, and capabilities.
	s.AddTool(
		mcplib.NewTool("context",
			mcplib.WithDescription("Get API domain context: resource taxonomy, auth requirements, query tips, and unique capabilities. Call this first."),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
		),
		handleContext,
	)

	// Runtime Cobra-tree mirror — exposes every user-facing command that is
	// not already covered by a typed endpoint or framework MCP tool.
	cobratree.RegisterAll(s, cli.RootCmd(), cobratree.SiblingCLIPath)
}

