// mcpToolError keeps provider-controlled typed endpoint errors within the MCP
// text-result budget just like successful endpoint results.
func mcpToolError(message string) *mcplib.CallToolResult {
	return mcplib.NewToolResultError(bound.Text(message))
}

func mcpToolPageResultText(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor string) *mcplib.CallToolResult {
	return mcpToolPageResultTextWithPlatform(method, data, pageConfig, cursor, nil)
}

func mcpToolPageResultTextWithPlatform(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor string, platformSession *platform.Session) *mcplib.CallToolResult {
	result := bound.EndpointPageResponse(method, data, bound.PageOptions{
		Cursor:         cursor,
		CursorParam:    pageConfig.CursorParam,
		NextCursorPath: pageConfig.NextCursorPath,
	})
	if platformSession != nil {
		result = bound.WithMetadata(result, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(result)
}

func newMCPClient(ctx context.Context) (*client.Client, *platform.Session, error) {
	cfg, err := newMCPConfig()
	if err != nil {
		return nil, nil, err
	}
	c := newMCPClientFromConfig(cfg)
	session, err := cli.BindMCPClient(ctx, c)
	if err != nil {
		return nil, nil, err
	}
	return c, session, nil
}

func newMCPConfig() (*config.Config, error) {
	cfg, err := config.Load("")
	if err != nil {
		return nil, fmt.Errorf("loading config: %w", err)
	}
	return cfg, nil
}

func newMCPClientFromConfig(cfg *config.Config) *client.Client {
	c := client.New(cfg, 60*time.Second, defaultMCPRateLimit)
	// Agents calling through MCP need fresh data every call. The on-disk
	// response cache survives across MCP server invocations, so a
	// DELETE/PATCH followed by a GET would otherwise return the
	// pre-mutation snapshot for up to the cache TTL. The interactive CLI
	// constructs its own client and is unaffected.
	c.NoCache = true
	return c
}

func mcpDBPath() (string, error) {
	dir, err := cliutil.DataDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "data.db"), nil
}

// toolResultJSON renders v as the indented JSON body of an MCP text result,
// surfacing a marshal failure as a tool error instead of empty content.
func toolResultJSON(v any) (*mcplib.CallToolResult, error) {
	text, err := bound.JSON(v)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}

func handleContext(_ context.Context, _ mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	paths := map[string]string{}
	if dir, err := cliutil.ConfigDir(); err == nil {
		paths["config_dir"] = dir
	}
	if dir, err := cliutil.DataDir(); err == nil {
		paths["data_dir"] = dir
	}
	if dir, err := cliutil.StateDir(); err == nil {
		paths["state_dir"] = dir
	}
	if dir, err := cliutil.CacheDir(); err == nil {
		paths["cache_dir"] = dir
	}
	ctx := map[string]any{
		"api":         "bestfoodtrucks",
		"description": "The only Best Food Trucks client that can tell you where a truck goes, not just what's parked outside today.",
		"archetype":   "generic",
		"tool_count":  1,
		"paths":       paths,
		// tool_surface tells agents which surface a capability lives on.
		"tool_surface": "MCP exposes typed endpoint tools plus a runtime mirror of user-facing CLI commands. Endpoint tools keep typed schemas; command-mirror tools shell out to the companion bestfoodtrucks-pp-cli binary.",
		// learn_protocol is generated from the single shared source of
		// truth (the exported constant internal/learn.RecallFirstProtocol)
		// also consumed by the CLI agent-context command, so the MCP and
		// CLI agent surfaces cannot drift.
		"learn_protocol": learn.RecallFirstProtocol,
		"resources": []map[string]any{
			{
				"name":        "graphql",
				"description": "Raw GraphQL passthrough against the Best Food Trucks API.",
				"endpoints":   []string{"query"},
				"searchable":  true,
			},
		},
		"query_tips": []string{
			"Pagination uses cursor-based paging. Pass after parameter for subsequent pages.",
			"Control page size with the limit parameter (default 100).",
		},
		// Command-mirror capabilities are exposed through MCP by shelling out
		// to the companion CLI binary.
		"command_mirror_capabilities": []map[string]string{
			{"name": "Digest", "command": "lot digest", "description": "Turns a lot's upcoming schedule into ready-to-paste announcement text instead of raw structured data.", "rationale": "Office coordinators currently hand-copy truck names and times from the website into Slack every week; this produces that exact text block in one command.", "via": "mcp-command-mirror"},
			{"name": "Cuisine Alert", "command": "trucks find", "description": "Finds every upcoming shift at a lot matching a cuisine, without opening each shift page one at a time.", "rationale": "The API only exposes cuisine tags nested one shift at a time under that shift's menu; no query filters the schedule by cuisine directly.", "via": "mcp-command-mirror"},
			{"name": "Truck Schedule", "command": "truck schedule", "description": "Shows every lot a specific truck visits, past and future — a view the Best Food Trucks website itself never built.", "rationale": "bestfoodtrucks.com is entirely lot-centric; there is no page anywhere on the site that lists everywhere a given truck goes.", "via": "mcp-command-mirror"},
			{"name": "Market Hotlist", "command": "market hotlist", "description": "Ranks trucks operating in a city by review signal, a cross-truck aggregate the site never computes.", "rationale": "Rating data is scoped per shift/order in the API; nothing on the live site ranks trucks against each other within a market.", "via": "mcp-command-mirror"},
			{"name": "Route Planner", "command": "lots digest", "description": "Combines multiple lots' schedules into one view in a single command instead of visiting each lot's page separately.", "rationale": "The website requires navigating to each lot's URL individually; there is no multi-lot combined schedule view.", "via": "mcp-command-mirror"},
		},
		"playbook": []map[string]string{
			{"topic": "Digest", "insight": "Office coordinators currently hand-copy truck names and times from the website into Slack every week; this produces that exact text block in one command."},
			{"topic": "Cuisine Alert", "insight": "The API only exposes cuisine tags nested one shift at a time under that shift's menu; no query filters the schedule by cuisine directly."},
			{"topic": "Truck Schedule", "insight": "bestfoodtrucks.com is entirely lot-centric; there is no page anywhere on the site that lists everywhere a given truck goes."},
			{"topic": "Market Hotlist", "insight": "Rating data is scoped per shift/order in the API; nothing on the live site ranks trucks against each other within a market."},
			{"topic": "Route Planner", "insight": "The website requires navigating to each lot's URL individually; there is no multi-lot combined schedule view."},
		},
	}
	return toolResultJSON(ctx)
}

